  ["bd055657c1f5a96c"] = { "Cerchi Hogral? Beh, hai controllato la taverna? Och! Se cerchi un ladro, e per giunta nano, dovresti cominciare dalla locanda! Va' a dare un'occhiata, su.", "." },
  ["bd12467dfdf865c3"] = { "Ci hai sfidati e siamo qui. Dov'è questo padrone di cui parli?", "." },
  ["bd139f642d3d2a6e"] = { "L'ombra del Vuoto è una creatura potente. Ricordo quando ero io al tuo posto, {name}. Con gli anni, la mia ombra del Vuoto ha imparato a combattermi meno, anche se sospetto che sia solo perché spera che io abbassi la guardia.\n\nRicordatelo, {name}.", "." },
