  ["bd27ad5f391ee9e3"] = { "Secondo me, la parte migliore della pesca è il suo ritmo lento. Ti dà il tempo di pensare, di riflettere sul passato e di fare progetti per il futuro.\n\nOh, ed è anche un'ottima scusa per bere. Parecchio.", "." },
  ["bd2cfa8479bf8a8c"] = { "Voglio comprare un'altra bomba puzzolente!", "." },
