  ["bd3b0a832ae4f653"] = { "È tutto raccolto, {class}. Tutto viene trasportato a ⟦Silithus=Silitus⟧ per i preparativi finali e dovrebbe arrivare entro un giorno. Tutte le nostre forze unite attendono l'<eroe/eroina> che completerà la riunificazione dello Scettro delle Sabbie Mutevoli, suonerà il gong e darà inizio alla Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧.", "." },
  ["bd46e33987a797bd"] = { "Non posso addestrarti. Devi parlare con l'istruttore della tua classe.", "." },
  ["bd4a8c1d1c0c2956"] = { "%s fa un respiro profondo", "." },
  ["bd56adb0f660095d"] = { "La mia vita non conta nulla! Il nostro sacro compito è tutto!", "." },
  ["bd5e2b1d38bca3d9"] = { "La tua presenza non è più gradita!", "." },
  ["bd691bf7136294ba"] = { "Ho da fare, {name}. Di' a Whuut di occuparsene, qualunque cosa sia. Quel cucciolo rimugina da tutto il giorno. Se continua così, finirà per rompere qualcosa.", "." },
  ["bd6b1d707cc1149c"] = { "Ho installato un nuovo dispositivo nel regolometro della matrice della nostra vettura. Dovrebbe aumentarne il quoziente di velocità di un fattore non inferiore a quindici!", "." },
  ["bd6fb3a6fe29bd47"] = { "I racconti delle tue gesta risuonano in tutto il ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧, <maestro/maestra> {name}.", "." },
  ["bd76e7df6927e22f"] = { "Ah sì, e consegnato puntualmente. Come sempre, è un piacere fare affari con te, Corbett.", "." },
  ["bd7a9e7249c9f01c"] = { "Ecco fatto: ora puoi fabbricare un ⟦Mana Well=Pozzo di Mana⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", "." },
  ["bd81dbc609feccf1"] = { "Sulle colline tra la ⟦Northshire=Contea del Nord⟧ e ⟦Stormwind=Roccavento⟧ vive un alchimista che potrebbe esserti d'aiuto. Perché non vai a fargli visita?", "." },
