  ["bd91a66a2544ab86"] = { "Si trova di solito sullo stormo cromatico minore: cuccioli, piccoli di drago, dragonidi minori.", "." },
  ["bda2b6db9bb96a3e"] = { "Accidenti! Neanche qui i pesci abboccano. Torno alla mia vecchia buca di pesca!", "." },
  ["bdaf005b935384b2"] = { "Quando il tempo lo permetterà, dovremo parlare a lungo. Abbiamo molto di cui discutere.", "." },
