  ["bdb72404d65aecdd"] = { "Aaaaahhh! Ero a un passo dalla fuga.", "." },
  ["bdb99298bbbba300"] = { "Sì, sì. Ti vedo.\n\nVa' per la tua strada. Forse ti sei <guadagnato/guadagnata> la fiducia di qualcuno, ma con me ci vorrà ben altro per dimostrarlo!", "." },
  ["bdbb467ff697e00e"] = { "Non posso aiutarti, {name}. Addestro solo i ladri.", "." },
  ["bdbe5e72dc9d39ce"] = { "È stata Umi a mandarti, vero?! Mi aveva detto di aspettarmi una sorpresa, ma non avrei mai pensato che intendesse questo!", "." },
  ["bdc4197d3534ef1c"] = { "Krathok, un tempo forgiavo armature e voglio riprendere in mano il martello! Insegnami la via del Fabbro d'Armature.", "." },
  ["bdc79895acd32bae"] = { "Come posso aiutarti?", "." },
  ["bdcc98fd71b9c1c1"] = { "Sento odore di intrusi...", "." },
  ["bdd0526097fe4877"] = { "Sai chi può davvero mostrarti qualcosa? Nogg! Va' a cercarlo a Orgrimmar.", "." },
  ["bdd0c9030d15e495"] = { "Vedi di non creare guai, {name}!", "." },
  ["bdd5a5949d7b2c79"] = { "Credi di poterti presentare da me e che io cominci a insegnarti? Ah! Devi fare la gavetta come tutti gli altri!", "." },
  ["bdd963713d014bc4"] = { "Abbiamo scelto di lasciare la protezione e le comodità delle Profondità per sfruttare... ehm, cioè... mmh, sì, proprio così, ESPLORARE il mondo.", "." },
  ["bdda3bc975e15bdf"] = { "Va' a Orgrimmar: troverai lei e la sua nidiata nella ⟦Valley of Honor=Valle dell'Onore⟧.", "." },
  ["bdde76c93a31d7ca"] = { "Ciao! Questo laboratorio non è mio, no! Ma un giorno, finito l'addestramento, mi metterò a inventare, proprio come il mio eroe, ⟦Marvon Rivetseeker=Marvon Cercachiodi⟧.\n\nNon l'hai mai sentito nominare? Be', guarda caso è partito parecchio tempo fa per studiare certe antiche rovine troll di cui parlava sempre. È partito con uno zeppelin... non so bene dove sia andato di preciso...\n\nTanarasin? Tenkeris? Taneranisany?\n\n<Liv scuote la testa.>\n\nNo, non è così...", "." },
  ["bddf00b996a0276f"] = { "I tempi sono cambiati. Le giovani razze si uniranno a noi. Non ci riuscirai mai.", "." },
  ["bde5759d24f25eb8"] = { "Finalmente ti ho raggiunto, Nefarian. Di certo non pensavi di sfuggire alla potenza degli altri Aspetti?", "." },
  ["bdf2e4ac63304bfa"] = { "È in questa notte che i nostri nemici ci temono di più. È in QUESTA notte che mostriamo ai nostri nemici cosa significa opporsi ai Reietti!", "." },
  ["bdf5fadd4d6a2c67"] = { "Ti do il benvenuto, {name}. E il Circolo di Smeraldo ti dà il benvenuto.\n\nSpero che insieme potremo aiutare a far rinascere e a proteggere questa foresta, un tempo possente. Molte forze cercano di distruggerla dall'esterno... e dall'interno.\n\nNon lasciarti sedurre dal potere di questo luogo: ti corromperebbe soltanto, come ha corrotto tutta questa terra.", "." },
